package com.byblack.filemanager;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.provider.DocumentsContract;import android.view.*;import android.widget.*;import java.text.*;import java.util.*;

public class MainActivity extends Activity{
 static final int PICK=7; static final int BG=Color.rgb(7,8,10),CARD=Color.rgb(20,21,25),RED=Color.rgb(255,48,48);
 LinearLayout content; TextView headTitle,headSub; Uri treeUri; String currentId; ArrayDeque<String> history=new ArrayDeque<>(); ArrayList<Item> files=new ArrayList<>(); int sortMode=0; boolean grid=false; String query="";
 static class Item{String id,name,mime;long size,time;boolean dir;Item(String i,String n,String m,long s,long t,boolean d){id=i;name=n;mime=m;size=s;time=t;dir=d;}}
 int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}
 GradientDrawable box(int color,int radius){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(radius));return g;}
 TextView text(String s,float z,int color){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(color);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
 @Override public void onCreate(Bundle b){super.onCreate(b);showHome();}

 LinearLayout shell(){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setBackgroundColor(BG);r.setPadding(dp(16),dp(12),dp(16),0);return r;}
 void top(LinearLayout root,String title,String sub){
  LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);
  TextView logo=text("B",26,RED);logo.setTypeface(null,1);logo.setGravity(Gravity.CENTER);logo.setBackground(box(Color.rgb(18,19,22),16));row.addView(logo,new LinearLayout.LayoutParams(dp(54),dp(54)));
  LinearLayout labels=new LinearLayout(this);labels.setOrientation(LinearLayout.VERTICAL);labels.setPadding(dp(14),0,0,0);
  headTitle=text(title,21,Color.WHITE);headTitle.setTypeface(null,1);headSub=text(sub,12,Color.GRAY);labels.addView(headTitle);labels.addView(headSub);row.addView(labels,new LinearLayout.LayoutParams(0,dp(58),1));
  TextView search=text("⌕",27,Color.WHITE);search.setGravity(Gravity.CENTER);search.setOnClickListener(v->searchDialog());row.addView(search,new LinearLayout.LayoutParams(dp(50),dp(50)));root.addView(row);
 }
 void showHome(){
  LinearLayout root=shell();top(root,"Byblack","File Manager");
  ScrollView sc=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);sc.addView(content);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));
  TextView welcome=text("Dosyaların tek yerde.",24,Color.WHITE);welcome.setTypeface(null,1);welcome.setPadding(0,dp(24),0,dp(4));content.addView(welcome);
  TextView hint=text("Hızlı, sade ve cihaz üzerinde.",13,Color.GRAY);hint.setPadding(0,0,0,dp(18));content.addView(hint);
  LinearLayout storage=card();TextView st=text("Dahili Depolama",18,Color.WHITE);st.setTypeface(null,1);TextView ss=text(treeUri==null?"Erişim vermek için dokun":"Depolama bağlı • Dosyaları aç",13,Color.LTGRAY);storage.addView(st);storage.addView(ss);storage.setOnClickListener(v->{if(treeUri==null)pick();else{currentId=DocumentsContract.getTreeDocumentId(treeUri);history.clear();showBrowser();}});content.addView(storage,lp(-1,92,0,0,0,14));
  section("Kategoriler");
  content.addView(pair("🖼","Resimler","🎬","Videolar"));content.addView(pair("🎵","Müzik","📄","Belgeler"));content.addView(pair("📦","APK","🗜","Arşivler"));content.addView(pair("⬇","İndirilenler","★","Favoriler"));
  section("Hızlı erişim");quick("📁","Tüm dosyalar","Klasörleri görüntüle",()->{if(treeUri==null)pick();else{currentId=DocumentsContract.getTreeDocumentId(treeUri);showBrowser();}});quick("↻","Son kullanılan konum","Kaldığın klasöre dön",()->{if(currentId!=null)showBrowser();else pick();});
  nav(root,0);setContentView(root);
 }
 LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setGravity(Gravity.CENTER_VERTICAL);c.setPadding(dp(18),dp(12),dp(18),dp(12));c.setBackground(box(CARD,18));return c;}
 LinearLayout.LayoutParams lp(int w,int h,int l,int t,int r,int b){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(w,h<0?h:dp(h));p.setMargins(dp(l),dp(t),dp(r),dp(b));return p;}
 void section(String s){TextView v=text(s,16,Color.WHITE);v.setTypeface(null,1);v.setPadding(0,dp(12),0,dp(10));content.addView(v);}
 LinearLayout pair(String ia,String a,String ib,String b){LinearLayout r=new LinearLayout(this);r.addView(category(ia,a),new LinearLayout.LayoutParams(0,dp(76),1));Space sp=new Space(this);r.addView(sp,new LinearLayout.LayoutParams(dp(10),1));r.addView(category(ib,b),new LinearLayout.LayoutParams(0,dp(76),1));r.setPadding(0,0,0,dp(10));return r;}
 LinearLayout category(String icon,String name){LinearLayout c=card();c.setOrientation(LinearLayout.HORIZONTAL);TextView i=text(icon,23,Color.WHITE);TextView n=text(name,15,Color.WHITE);n.setPadding(dp(10),0,0,0);c.addView(i);c.addView(n);c.setOnClickListener(v->{if(treeUri==null)pick();else{currentId=DocumentsContract.getTreeDocumentId(treeUri);showBrowser();}});return c;}
 interface Run{void go();}
 void quick(String i,String a,String b,Run run){LinearLayout c=card();c.setOrientation(LinearLayout.HORIZONTAL);TextView ic=text(i,24,RED);ic.setGravity(Gravity.CENTER);c.addView(ic,new LinearLayout.LayoutParams(dp(50),-1));LinearLayout z=new LinearLayout(this);z.setOrientation(LinearLayout.VERTICAL);TextView n=text(a,16,Color.WHITE),m=text(b,12,Color.GRAY);z.addView(n);z.addView(m);c.addView(z,new LinearLayout.LayoutParams(0,-1,1));c.setOnClickListener(v->run.go());content.addView(c,lp(-1,72,0,0,0,10));}

 void nav(LinearLayout root,int active){LinearLayout n=new LinearLayout(this);n.setGravity(Gravity.CENTER);String[] a={"⌂\nAna Ekran","□\nKlasörler","⋮\nAraçlar"};for(int i=0;i<3;i++){TextView v=text(a[i],12,i==active?RED:Color.LTGRAY);v.setGravity(Gravity.CENTER);final int k=i;v.setOnClickListener(x->{if(k==0)showHome();else if(k==1){if(treeUri==null)pick();else{if(currentId==null)currentId=DocumentsContract.getTreeDocumentId(treeUri);showBrowser();}}else tools();});n.addView(v,new LinearLayout.LayoutParams(0,dp(64),1));}root.addView(n);}
 void pick(){startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),PICK);}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==PICK&&c==RESULT_OK&&d!=null){treeUri=d.getData();int f=d.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);try{getContentResolver().takePersistableUriPermission(treeUri,f);}catch(Exception ignored){}currentId=DocumentsContract.getTreeDocumentId(treeUri);history.clear();showBrowser();}}

 void showBrowser(){
  if(treeUri==null||currentId==null){pick();return;}LinearLayout root=shell();top(root,"Dosyalar",pretty(currentId));
  LinearLayout bar=new LinearLayout(this);bar.setPadding(0,dp(12),0,dp(10));
  tool(bar,"‹",v->backFolder());tool(bar,"+",v->newFolder());tool(bar,grid?"☷":"▦",v->{grid=!grid;render();});tool(bar,"↕",v->sortDialog());root.addView(bar);
  ScrollView sc=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);sc.addView(content);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));nav(root,1);setContentView(root);load();
 }
 void tool(LinearLayout b,String s,View.OnClickListener l){TextView v=text(s,23,Color.WHITE);v.setGravity(Gravity.CENTER);v.setBackground(box(CARD,14));v.setOnClickListener(l);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(48),1);p.setMargins(dp(3),0,dp(3),0);b.addView(v,p);}
 Uri doc(String id){return DocumentsContract.buildDocumentUriUsingTree(treeUri,id);}
 void load(){files.clear();try{Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(treeUri,currentId);String[] p={DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_SIZE,DocumentsContract.Document.COLUMN_LAST_MODIFIED};try(android.database.Cursor c=getContentResolver().query(children,p,null,null,null)){while(c!=null&&c.moveToNext()){String id=c.getString(0),n=c.getString(1),m=c.getString(2);long s=c.isNull(3)?-1:c.getLong(3),t=c.isNull(4)?0:c.getLong(4);files.add(new Item(id,n,m,s,t,DocumentsContract.Document.MIME_TYPE_DIR.equals(m)));}}render();}catch(Exception e){Toast.makeText(this,"Klasör okunamadı: "+e.getMessage(),Toast.LENGTH_LONG).show();}}
 void render(){if(content==null)return;content.removeAllViews();ArrayList<Item>a=new ArrayList<>();for(Item i:files)if(query.isEmpty()||i.name.toLowerCase(Locale.ROOT).contains(query))a.add(i);Collections.sort(a,(x,y)->{if(x.dir!=y.dir)return x.dir?-1:1;if(sortMode==1)return Long.compare(y.time,x.time);if(sortMode==2)return Long.compare(y.size,x.size);return x.name.compareToIgnoreCase(y.name);});
  if(grid){GridLayout g=new GridLayout(this);g.setColumnCount(2);for(Item i:a){LinearLayout c=fileCard(i,true);GridLayout.LayoutParams p=new GridLayout.LayoutParams();p.width=0;p.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1,1f);p.setMargins(dp(4),dp(4),dp(4),dp(4));g.addView(c,p);}content.addView(g);}else for(Item i:a)content.addView(fileCard(i,false),lp(-1,68,0,0,0,5));
 }
 LinearLayout fileCard(Item i,boolean compact){LinearLayout r=card();r.setOrientation(compact?LinearLayout.VERTICAL:LinearLayout.HORIZONTAL);TextView ic=text(icon(i),compact?28:23,Color.WHITE);ic.setGravity(Gravity.CENTER);r.addView(ic,new LinearLayout.LayoutParams(compact?-1:dp(52),compact?dp(42):-1));LinearLayout z=new LinearLayout(this);z.setOrientation(LinearLayout.VERTICAL);TextView n=text(i.name,compact?14:16,Color.WHITE);n.setSingleLine(true);TextView m=text(i.dir?"Klasör":human(i.size),11,Color.GRAY);z.addView(n);z.addView(m);r.addView(z,new LinearLayout.LayoutParams(0,-1,1));r.setOnClickListener(v->{if(i.dir){history.push(currentId);currentId=i.id;showBrowser();}else open(i);});r.setOnLongClickListener(v->{menu(i);return true;});return r;}
 String icon(Item i){if(i.dir)return"📁";String n=i.name.toLowerCase();if(n.endsWith(".apk"))return"📦";if(n.matches(".*\\.(jpg|jpeg|png|webp)$"))return"🖼";if(n.matches(".*\\.(mp4|mkv|avi)$"))return"🎬";if(n.matches(".*\\.(mp3|wav|flac)$"))return"🎵";if(n.endsWith(".pdf"))return"📕";if(n.matches(".*\\.(zip|rar|7z)$"))return"🗜";return"📄";}
 void searchDialog(){if(treeUri==null){pick();return;}EditText e=new EditText(this);e.setHint("Dosya adı");e.setText(query);new AlertDialog.Builder(this).setTitle("Ara").setView(e).setPositiveButton("ARA",(d,w)->{query=e.getText().toString().trim().toLowerCase(Locale.ROOT);if(currentId==null)currentId=DocumentsContract.getTreeDocumentId(treeUri);showBrowser();}).setNeutralButton("TEMİZLE",(d,w)->{query="";showBrowser();}).show();}
 void sortDialog(){new AlertDialog.Builder(this).setTitle("Sırala").setItems(new String[]{"Ad A-Z","En yeni","En büyük"},(d,w)->{sortMode=w;render();}).show();}
 void menu(Item i){new AlertDialog.Builder(this).setTitle(i.name).setItems(new String[]{"Aç","Yeniden adlandır","Paylaş","Detaylar","Sil"},(d,w)->{if(w==0){if(i.dir){history.push(currentId);currentId=i.id;showBrowser();}else open(i);}else if(w==1)rename(i);else if(w==2)share(i);else if(w==3)details(i);else delete(i);}).show();}
 void open(Item i){try{startActivity(new Intent(Intent.ACTION_VIEW).setDataAndType(doc(i.id),i.mime==null?"*/*":i.mime).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}catch(Exception e){Toast.makeText(this,"Dosyayı açacak uygulama bulunamadı.",0).show();}}
 void share(Item i){if(i.dir)return;Intent x=new Intent(Intent.ACTION_SEND);x.setType(i.mime==null?"*/*":i.mime);x.putExtra(Intent.EXTRA_STREAM,doc(i.id));x.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(x,"Paylaş"));}
 void details(Item i){new AlertDialog.Builder(this).setTitle("Detaylar").setMessage("Ad: "+i.name+"\nTür: "+(i.dir?"Klasör":i.mime)+"\nBoyut: "+human(i.size)+"\nDeğiştirme: "+date(i.time)+"\nKonum: "+pretty(currentId)).setPositiveButton("TAMAM",null).show();}
 void rename(Item i){EditText e=new EditText(this);e.setText(i.name);new AlertDialog.Builder(this).setTitle("Yeniden adlandır").setView(e).setPositiveButton("KAYDET",(d,w)->{String n=e.getText().toString().trim();if(n.isEmpty())return;try{DocumentsContract.renameDocument(getContentResolver(),doc(i.id),n);load();}catch(Exception z){Toast.makeText(this,"Yeniden adlandırılamadı.",0).show();}}).setNegativeButton("İPTAL",null).show();}
 void delete(Item i){new AlertDialog.Builder(this).setTitle("Silinsin mi?").setMessage(i.name+" kalıcı olarak silinecek.").setPositiveButton("SİL",(d,w)->{try{DocumentsContract.deleteDocument(getContentResolver(),doc(i.id));load();}catch(Exception z){Toast.makeText(this,"Silinemedi.",0).show();}}).setNegativeButton("İPTAL",null).show();}
 void newFolder(){EditText e=new EditText(this);e.setHint("Klasör adı");new AlertDialog.Builder(this).setTitle("Yeni klasör").setView(e).setPositiveButton("OLUŞTUR",(d,w)->{String n=e.getText().toString().trim();if(n.isEmpty())return;try{DocumentsContract.createDocument(getContentResolver(),doc(currentId),DocumentsContract.Document.MIME_TYPE_DIR,n);load();}catch(Exception z){Toast.makeText(this,"Klasör oluşturulamadı.",0).show();}}).setNegativeButton("İPTAL",null).show();}
 void backFolder(){query="";if(!history.isEmpty()){currentId=history.pop();showBrowser();}else showHome();}
 @Override public void onBackPressed(){if(currentId!=null&&!history.isEmpty())backFolder();else showHome();}
 void tools(){new AlertDialog.Builder(this).setTitle("Byblack Araçlar").setItems(new String[]{"Yeni klasör","Ara","Sırala","Liste / Izgara"},(d,w)->{if(currentId==null){pick();return;}if(w==0)newFolder();else if(w==1)searchDialog();else if(w==2)sortDialog();else{grid=!grid;showBrowser();}}).show();}
 String pretty(String id){if(id==null)return"Dahili Depolama";int p=id.indexOf(':');String x=p>=0?id.substring(p+1):id;return x.isEmpty()?"Dahili Depolama":"Dahili Depolama / "+x;}
 String human(long n){if(n<0)return"-";if(n<1024)return n+" B";if(n<1048576)return String.format(Locale.US,"%.1f KB",n/1024d);if(n<1073741824)return String.format(Locale.US,"%.1f MB",n/1048576d);return String.format(Locale.US,"%.2f GB",n/1073741824d);}
 String date(long t){return t<=0?"-":new SimpleDateFormat("dd.MM.yyyy HH:mm",Locale.getDefault()).format(new Date(t));}
}